// Hydra video synth skeleton -- globals only, no imports, one chain ending in .out()
osc(12, 0.08, 1.4)
  .rotate(shape(2))
  .scale(noise(3, 0.2))
  .kaleid(noise(4))
  .repeat(shape(2))
  .modulate(voronoi(0.8, 0.5), 0.15)
  .add(gradient(0.5, 0.3))
  .blend(noise(3, 0.2), 0.45)
  .diff(voronoi(0.7, 0.6))
  .color(noise(0.7), 0.9, 1.0)
  .out()